using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Application;

public sealed class CalculatePayableTotalTests
{
    private readonly CalculatePayableTotal _sut = new();

    [Theory]
    // Each band threshold belongs to the band above it, so a larger order can pay less
    [InlineData(LoyaltyTier.Bronze, 49.99, 47.50)]
    [InlineData(LoyaltyTier.Bronze, 50.00, 47.00)]
    [InlineData(LoyaltyTier.Silver, 199.99, 184.00)]
    [InlineData(LoyaltyTier.Silver, 200.00, 180.00)]
    // The ceiling holds the effective rate at 10 points, so Gold stops gaining
    [InlineData(LoyaltyTier.Gold, 20.00, 18.20)]
    [InlineData(LoyaltyTier.Gold, 100.00, 90.00)]
    [InlineData(LoyaltyTier.Gold, 200.00, 180.00)]
    // A part cent of discount is dropped, never rounded up
    [InlineData(LoyaltyTier.Silver, 30.10, 28.00)]
    [InlineData(LoyaltyTier.Bronze, 250.12, 230.12)]
    public void PayableTotalVariesByLoyaltyTierAndOrderSize(LoyaltyTier tier, decimal subtotal, decimal expectedPayable)
    {
        var payable = _sut.For(tier, subtotal);

        Assert.Equal(expectedPayable, payable);
    }
}
EOF

